function safe(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}
function yr(x){return parseInt(x.sort.slice(0,4),10)}
function decadeOf(x){return Math.floor(yr(x)/10)*10}
function mappedLocations(item){return item.track_ids.map(id=>locBy[id]).filter(x=>x&&x.lat!=null&&x.lon!=null)}
function pinClass(loc){if(loc.location_state==='SITE_POINT_APPROXIMATE')return 'approx'; if(loc.location_state==='EXACT_HISTORICAL_TRACK_POINT')return 'historical'; return 'current'}
function coords(loc){return {x:(loc.lon-FRAME.W)/(FRAME.E-FRAME.W)*MAP.W,y:(FRAME.N-loc.lat)/(FRAME.N-FRAME.S)*MAP.H}}
function mapMarkup(item){
  const mapped=mappedLocations(item);
  const marks=mapped.map(loc=>{const p=coords(loc),cls=pinClass(loc),labelX=Math.min(p.x+24,MAP.W-18),labelY=Math.max(34,Math.min(p.y-18,MAP.H-18));return `<a class="tl-map-link" href="../tracks/${safe(loc.track_id)}/index.html" aria-label="Open ${safe(loc.name)} track profile"><g class="tl-map-marker ${cls}"><title>${safe(loc.name)}</title><circle class="tl-map-circle" cx="${p.x.toFixed(3)}" cy="${p.y.toFixed(3)}" r="18"></circle><text class="tl-map-label" x="${labelX.toFixed(3)}" y="${labelY.toFixed(3)}">${safe(loc.name)}</text></g></a>`}).join('');
  return `<svg class="tl-map-canvas" viewBox="0 0 ${MAP.W} ${MAP.H}" role="img" aria-label="Arizona geographic reference map with ${mapped.length} governed marker${mapped.length===1?'':'s'}"><image href="../arizona-geographic-absolute.svg" x="0" y="0" width="${MAP.W}" height="${MAP.H}"></image>${marks}</svg>`;
}
function mapNote(item){
 const mapped=mappedLocations(item); const linked=item.track_ids.length;
 if(!linked) return 'No governed track record is attached to this milestone, so the Timeline does not invent a geographic marker.';
 if(!mapped.length) return `${linked} linked track record${linked===1?' is':'s are'} not plotted because no defensible registered coordinate exists for this milestone.`;
 const exact=mapped.filter(x=>x.location_state==='EXACT_TRACK_POINT').length, hist=mapped.filter(x=>x.location_state==='EXACT_HISTORICAL_TRACK_POINT').length, approx=mapped.filter(x=>x.location_state==='SITE_POINT_APPROXIMATE').length;
 return `${mapped.length} governed point${mapped.length===1?'':'s'} shown from the A4 register: ${exact} exact/current · ${hist} exact historical · ${approx} site approximate. Unregistered linked tracks remain unpinned.`;
}
function links(item){
 const parts=[];
 item.claim_ids.forEach(id=>parts.push(`<a href="../../research/claims/${safe(id)}/index.html">Claim ${safe(id)} →</a>`));
 item.track_ids.forEach(id=>parts.push(`<a href="../tracks/${safe(id)}/index.html">Track ${safe(id)} →</a>`));
 item.event_ids.forEach(id=>parts.push(`<a href="../events/index.html#${safe(id)}">Event ${safe(id)} →</a>`));
 return parts.join('') || '<span>No linked public drilldown record in this layer.</span>';
}
function boundary(item){
 if(item.question) return '<strong>Open-question layer.</strong> This record is deliberately excluded from the settled chronology by default. Its purpose is to preserve a research problem, not manufacture a milestone.';
 if(item.date_precision==='OPEN') return '<strong>Date state: OPEN.</strong> The chronology does not assign an exact date.';
 return `<strong>Date precision:</strong> ${safe(item.date_precision)}. The displayed date is preserved exactly at that governed level.`;
}
function primaryDrilldown(item){
 if(item.claim_ids.length)return `../../research/claims/${safe(item.claim_ids[0])}/index.html`;
 if(item.track_ids.length)return `../tracks/${safe(item.track_ids[0])}/index.html`;
 if(item.event_ids.length)return `../events/index.html#${safe(item.event_ids[0])}`;
 return '';
}
function crosswalkControls(item){const bits=[];if(item.claim_ids.length)bits.push(`<button class="chrono-count-control chrono-inspect" type="button" aria-label="Inspect ${item.claim_ids.length} linked claim${item.claim_ids.length===1?'':'s'}">${item.claim_ids.length} claim${item.claim_ids.length===1?'':'s'} →</button>`);if(item.track_ids.length)bits.push(`<button class="chrono-count-control chrono-inspect" type="button" aria-label="Inspect ${item.track_ids.length} linked track${item.track_ids.length===1?'':'s'}">${item.track_ids.length} track link${item.track_ids.length===1?'':'s'} →</button>`);if(item.event_ids.length)bits.push(`<button class="chrono-count-control chrono-inspect" type="button" aria-label="Inspect ${item.event_ids.length} linked event${item.event_ids.length===1?'':'s'}">${item.event_ids.length} event link${item.event_ids.length===1?'':'s'} →</button>`);if(!bits.length)bits.push(`<button class="chrono-count-control chrono-inspect" type="button">Inspect evidence crosswalk →</button>`);return bits.join('')}
function card(item){const primary=primaryDrilldown(item);const href=primary||'#timeline-inspector';const title=`<a class="chrono-title-link" href="${href}">${safe(item.title)} →</a>`;const role=primary?'link':'button';const aria=primary?`Open ${safe(item.title)}`:`Inspect evidence crosswalk for ${safe(item.title)}`;return `<article class="chrono-item ${item.question?'question':''} ${item.timeline_id===selectedId?'selected':''}" data-id="${safe(item.timeline_id)}"><div class="chrono-date"><strong>${safe(item.display_date)}</strong><span>${safe(item.date_precision)}</span></div><div class="chrono-card" role="${role}" tabindex="0" data-primary-href="${primary}" aria-label="${aria}"><div class="chrono-badges"><span>${safe(item.type)}</span><span>${safe(item.status)}</span></div><h3>${title}</h3><p>${safe(item.summary)}</p><div class="chrono-crosswalk">${crosswalkControls(item)}</div></div></article>`}
function filtered(){const q=(search.value||'').toLowerCase().trim();return TIMELINE_DATA.filter(x=>{if(x.question&&!questions.checked)return false;if(type.value&&x.type!==type.value)return false;if(place.value&&x.city!==place.value)return false;if(decade&&String(decadeOf(x))!==decade)return false;const hay=[x.display_date,x.date_precision,x.title,x.type,x.city,x.status,x.summary,...x.claim_ids,...x.track_ids,...x.event_ids].join(' ').toLowerCase();return !q||hay.includes(q)})}
function paintInspector(item){
 const set=(sel,val)=>{const el=document.querySelector(sel);if(el)el.innerHTML=val};
 const href=primaryDrilldown(item)||'#timeline-inspector';
 document.querySelector('.timeline-feature')?.setAttribute('data-primary-href',href);
 document.querySelector('[data-inspector]')?.setAttribute('data-primary-href',href);
 set('[data-i-date]',safe(item.display_date));set('[data-i-title]',`<a class="inspector-title-link" href="${href}">${safe(item.title)} →</a>`);set('[data-i-summary]',safe(item.summary));set('[data-i-badges]',`<span>${safe(item.type)}</span><span>${safe(item.status)}</span><span>${safe(item.date_precision)}</span>`);set('[data-i-map]',mapMarkup(item));set('[data-i-map-note]',safe(mapNote(item)));set('[data-i-links]',links(item));set('[data-i-boundary]',boundary(item));
 document.getElementById('selectedId').textContent=item.timeline_id;document.getElementById('selectedDate').textContent=item.display_date;document.getElementById('selectedTitle').innerHTML=`<a class="feature-title-link" href="${href}">${safe(item.title)} →</a>`;document.getElementById('selectedSummary').textContent=item.summary;document.getElementById('selectedBadges').innerHTML=`<span>${safe(item.type)}</span><span>${safe(item.status)}</span><span>${safe(item.date_precision)}</span>`;document.getElementById('selectedMap').innerHTML=mapMarkup(item);document.getElementById('selectedMapNote').textContent=mapNote(item);document.getElementById('selectedLinks').innerHTML=links(item);
}
function inspectCard(cardEl){selectedId=cardEl.closest('.chrono-item').dataset.id;render();document.querySelector('[data-inspector]').scrollIntoView({behavior:'smooth',block:'nearest'})}
function render(){const rows=filtered();count.textContent=rows.length;list.innerHTML=rows.length?rows.map(card).join(''):'<div class="timeline-empty">No timeline records match those filters.</div>';if(!rows.some(x=>x.timeline_id===selectedId)&&rows.length)selectedId=rows[0].timeline_id;const sel=TIMELINE_DATA.find(x=>x.timeline_id===selectedId)||rows[0];if(sel)paintInspector(sel);list.querySelectorAll('.chrono-inspect').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();inspectCard(b)}));list.querySelectorAll('.chrono-card').forEach(c=>{const activate=e=>{if(e.target.closest('a,button,input,select,textarea,label'))return;const href=c.dataset.primaryHref;if(href){window.location.href=href}else{inspectCard(c)}};c.addEventListener('click',activate);c.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('a,button,input,select,textarea,label')){e.preventDefault();activate(e)}})})}
[search,type,place,questions].forEach(el=>el.addEventListener(el===search?'input':'change',render));
document.querySelectorAll('[data-decade]').forEach(b=>b.addEventListener('click',()=>{decade=b.dataset.decade;document.querySelectorAll('[data-decade]').forEach(x=>x.classList.toggle('active',x===b));render()}));
function activatePrimaryPanel(panel){if(!panel)return;panel.setAttribute('role','link');if(!panel.hasAttribute('tabindex'))panel.tabIndex=0;const activate=event=>{if(event.target.closest('a,button,input,select,textarea,label'))return;const href=panel.dataset.primaryHref;if(href&&href!=='#timeline-inspector')window.location.href=href};panel.addEventListener('click',activate);panel.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&!event.target.closest('a,button,input,select,textarea,label')){event.preventDefault();activate(event)}})}
activatePrimaryPanel(document.querySelector('.timeline-feature'));
activatePrimaryPanel(document.querySelector('[data-inspector]'));
const menu=document.querySelector('.menu-toggle'),nav=document.getElementById('primaryNav');menu?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});
render();
